<?php /** @var \Sysfera\Plugin $sf @var array $teams @var array $emps @var array $whs */
include __DIR__ . '/_nav.php'; $may = $c->can('hr.teams.manage'); $names = array_column($emps, 'full_name', 'uuid'); ?>
<div class="page-h"><h1><?= e($sf->t('nav_teams')) ?></h1></div>
<?php foreach ($teams as $t): ?><div class="card"><h3><?= e($t['name']) ?> <?php if (!(int)$t['active']): ?><span class="hr-st bad"><?= e($sf->t('inactive')) ?></span><?php endif; ?></h3>
  <p class="muted"><?= e($t['descr']) ?> · <?= e($sf->t('f_warehouse')) ?>: <?= e(array_column($whs, 'name', 'id')[$t['warehouse_id']] ?? '—') ?> · <?= e($sf->t('f_mission')) ?>: <?= $t['mission_ref'] ? '#' . (int)$t['mission_ref'] : '—' ?></p>
  <p><?php foreach ($t['members'] as $m): if ($m['role'] === 'removed') continue; ?><a class="hr-st <?= $m['role'] === 'lead' ? 'ok' : '' ?>" href="<?= e($sf->url('/employees/' . $m['employee_uuid'])) ?>"><?= e($names[$m['employee_uuid']] ?? $m['employee_uuid']) ?><?= $m['role'] === 'lead' ? ' ★' : '' ?></a> <?php endforeach; ?></p>
  <?php if ($may): ?>
  <form method="post" action="<?= e($sf->url('/do/teams.member')) ?>" class="row"><?= csrf_field() ?><input type="hidden" name="return" value="/teams"><input type="hidden" name="uuid" value="<?= e($t['uuid']) ?>">
    <select name="employee_uuid"><?php foreach ($emps as $x): ?><option value="<?= e($x['uuid']) ?>"><?= e($x['full_name']) ?></option><?php endforeach; ?></select><select name="role"><option value="member"><?= e($sf->t('tr_member')) ?></option><option value="lead"><?= e($sf->t('tr_lead')) ?></option></select>
    <button class="btn sm primary"><?= e($sf->t('add')) ?></button><button class="btn sm" name="remove" value="1"><?= e($sf->t('remove')) ?></button></form>
  <form method="post" action="<?= e($sf->url('/do/teams.save')) ?>" class="row"><?= csrf_field() ?><input type="hidden" name="return" value="/teams"><input type="hidden" name="uuid" value="<?= e($t['uuid']) ?>"><input name="name" value="<?= e($t['name']) ?>" required><input name="descr" value="<?= e($t['descr']) ?>">
    <select name="warehouse_id"><option value=""></option><?php foreach ($whs as $w): ?><option value="<?= (int)$w['id'] ?>" <?= (int)$t['warehouse_id'] === (int)$w['id'] ? 'selected' : '' ?>><?= e($w['name']) ?></option><?php endforeach; ?></select>
    <input name="mission_ref" value="<?= e((string)$t['mission_ref']) ?>" placeholder="<?= e($sf->t('f_mission')) ?> #" size="6" inputmode="numeric"><button class="btn sm primary"><?= e($sf->t('save')) ?></button></form><?php endif; ?></div><?php endforeach; ?>
<?php if ($may): ?><div class="card"><h3><?= e($sf->t('team_new')) ?></h3><form method="post" action="<?= e($sf->url('/do/teams.save')) ?>" class="row"><?= csrf_field() ?><input type="hidden" name="return" value="/teams"><input name="name" required placeholder="<?= e($sf->t('f_name')) ?>"><input name="descr" placeholder="<?= e($sf->t('f_descr')) ?>">
  <select name="warehouse_id"><option value=""></option><?php foreach ($whs as $w): ?><option value="<?= (int)$w['id'] ?>"><?= e($w['name']) ?></option><?php endforeach; ?></select><input name="mission_ref" placeholder="<?= e($sf->t('f_mission')) ?> #" size="6" inputmode="numeric"><button class="btn primary"><?= e($sf->t('add')) ?></button></form></div><?php endif; ?>
